// Do not edit this file as it will be overwritten if HAMR codegen is rerun

//! Inspection and injection over the component ports and GUMBO state variables.

use data::*;

/// Scheduler channel per thread, for `api::run_to_thread(..)`.  Parking immediately
/// before a thread is what makes injection into a port with a real producer
/// reliable: step past that producer's own slot and it overwrites the value.
pub mod channels {
  pub const gen_gen_MON: u32 = 2;
  pub const splitter_splitter_MON: u32 = 3;
  pub const incx_incx_MON: u32 = 4;
  pub const decy_decy_MON: u32 = 5;
  pub const clampx_clampx_MON: u32 = 6;
  pub const merger_merger_MON: u32 = 7;
  pub const consume_consume_MON: u32 = 8;
}

extern "C" {
  fn test_get_gen_gen_outstruct(value: *mut SysPropStructSplit_Data_Model::StructXY) -> bool;
  fn test_put_gen_gen_outstruct(value: *mut SysPropStructSplit_Data_Model::StructXY);
  fn test_get_splitter_splitter_xfield(value: *mut i32) -> bool;
  fn test_put_splitter_splitter_xfield(value: *mut i32);
  fn test_get_splitter_splitter_yfield(value: *mut i32) -> bool;
  fn test_put_splitter_splitter_yfield(value: *mut i32);
  fn test_get_incx_incx_outxfield(value: *mut i32) -> bool;
  fn test_put_incx_incx_outxfield(value: *mut i32);
  fn test_get_clampx_clampx_outxfield(value: *mut i32) -> bool;
  fn test_put_clampx_clampx_outxfield(value: *mut i32);
  fn test_get_decy_decy_outyfield(value: *mut i32) -> bool;
  fn test_put_decy_decy_outyfield(value: *mut i32);
  fn test_get_merger_merger_outstruct(value: *mut SysPropStructSplit_Data_Model::StructXY) -> bool;
  fn test_put_merger_merger_outstruct(value: *mut SysPropStructSplit_Data_Model::StructXY);
  fn test_get_consume_consume_sv_last_x(value: *mut i32) -> bool;
  fn test_put_consume_consume_sv_last_x(value: *mut i32);
}

/// Current value of the port `gen_gen_outstruct`, or None when nothing is queued.
pub fn get_gen_gen_outstruct() -> Option<SysPropStructSplit_Data_Model::StructXY> {
  unsafe {
    let mut v: SysPropStructSplit_Data_Model::StructXY = SysPropStructSplit_Data_Model::StructXY::default();
    if test_get_gen_gen_outstruct(&mut v) { Some(v) } else { None }
  }
}

/// Publish `value` to the port `gen_gen_outstruct`, as its producer would.
pub fn put_gen_gen_outstruct(value: SysPropStructSplit_Data_Model::StructXY) {
  unsafe {
    let mut v = value;
    test_put_gen_gen_outstruct(&mut v);
  }
}

